// guessed at, since a string that failed to parse cannot be shown to hold no
// credential.
func withoutUserinfo(raw string) string {
	if raw == "" {
		return ""
	}
	u, err := url.Parse(raw)
	if err != nil {
		return ""
	}
	if u.Scheme == "" {
		return raw
	}
	u.User = nil
	return u.String()
}

