	want := []struct{ name, status string }{{"up", "OK"}, {"broken", "ERROR"}, {"gone", "DOWN"}}
	for i, w := range want {
		m := out.Monitors[i]
		if m.Name != w.name || m.Status != w.status {
			t.Errorf("monitor %d = %s/%s, want %s/%s", i, m.Name, m.Status, w.name, w.status)
