func TestARequestArrivingBeforeTheListingWaitsInsteadOfRefusing(t *testing.T) {
	m := New(config.Default(), nil)

	updated, cmd := m.Update(ScanRequestedMsg{Paths: []string{"/repo"}, Invocation: "1"})
